/**
 * `repr()` for strings, matching CPython closely enough for CLI diagnostics.
 *
 * argparse embeds the offending value with `%r`, so the quoting and escaping
 * rules are observable in the program's stderr.
 */

import { isPyPrintable } from './unicode-data.mjs';

const HEX_DIGITS = '0123456789abcdef';

function toHex(value, width) {
  let out = '';
  let rest = value;
  while (rest > 0) {
    out = HEX_DIGITS[rest % 16] + out;
    rest = Math.floor(rest / 16);
  }
  return out.padStart(width, '0');
}

function escapeCodePoint(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return `\\x${toHex(cp, 2)}`;
  if (cp < 0x10000) return `\\u${toHex(cp, 4)}`;
  return `\\U${toHex(cp, 8)}`;
}

/**
 * Render `value` the way `repr()` would: single quotes by default, double
 * quotes when the text contains a single quote but no double quote.
 */
export function pyRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of value) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += `\\${ch}`;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPyPrintable(ch)) {
      out += ch;
    } else {
      out += escapeCodePoint(ch);
    }
  }
  return out + quote;
}

/**
 * Unicode tables required to reproduce CPython's `int(str)` acceptance rules.
 *
 * `int()` is far more permissive than an ASCII-only parser: it strips Unicode
 * whitespace and accepts any character in general category Nd, using that
 * character's decimal value.  Both tables below are static data, so no runtime
 * scanning (and no external dependency) is needed.
 */

/**
 * Start code points of every ten-code-point decimal-digit run (category Nd).
 * A character `cp` in `[start, start + 9]` has decimal value `cp - start`.
 *
 * Derived by walking the full code space with the `\p{Nd}` property escape and
 * splitting each contiguous run into aligned groups of ten -- Unicode always
 * encodes a decimal digit set as ten consecutive code points.
 */
export const DECIMAL_DIGIT_RUN_STARTS = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
  0x11d50, 0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8,
  0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

/**
 * Code points CPython treats as whitespace when trimming a numeric literal
 * (`Py_UNICODE_ISSPACE`).  Ranges are inclusive `[lo, hi]` pairs.
 */
const WHITESPACE_RANGES = [
  [0x0009, 0x000d], [0x001c, 0x0020], [0x0085, 0x0085], [0x00a0, 0x00a0],
  [0x1680, 0x1680], [0x2000, 0x200a], [0x2028, 0x2029], [0x202f, 0x202f],
  [0x205f, 0x205f], [0x3000, 0x3000],
];

/**
 * Decimal value of `cp`, or -1 when `cp` is not a decimal digit.
 * Binary search over the run table.
 */
export function decimalDigitValue(cp) {
  let lo = 0;
  let hi = DECIMAL_DIGIT_RUN_STARTS.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const start = DECIMAL_DIGIT_RUN_STARTS[mid];
    if (cp < start) {
      hi = mid - 1;
    } else if (cp > start + 9) {
      lo = mid + 1;
    } else {
      return cp - start;
    }
  }
  return -1;
}

/** True when `cp` is stripped from the ends of a numeric literal. */
export function isPyWhitespace(cp) {
  for (const [lo, hi] of WHITESPACE_RANGES) {
    if (cp >= lo && cp <= hi) return true;
  }
  return false;
}

/**
 * True when a character is printable in Python's sense, i.e. `str.isprintable`
 * -- everything except categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs, with
 * U+0020 explicitly printable.  Used by `repr()` for CLI error messages.
 */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

export function isPyPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}
